#include <stdio.h>

int digit_root(int n) {
    while (n >= 10) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        n = sum;
    }
    return n;
}

int main() {
    printf("%d\n", digit_root(9875));
    printf("%d\n", digit_root(6789));
    return 0;
}
